// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    function testFuzz_property(address attacker, bytes calldata data) public {
        vm.assume(attacker != address(0));

        Malicious mal = new Malicious();

        vm.deal(address(c), 1 ether);

        bytes memory payload = abi.encodeWithSelector(Malicious.kamikaze.selector, attacker);

        bool ok;
        try c.forward(address(mal), payload) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(address(c).balance == 1 ether);
    }
}

contract Malicious {
    function kamikaze(address payable to) public payable {
        selfdestruct(to);
    }
}
